def page_size(value=None, *, max_limit=100):
    if type(max_limit) is not int:
        raise TypeError("max_limit must be an integer")
    if not 1 <= max_limit <= 500:
        raise ValueError("max_limit out of range")
    if value is None:
        if 10 > max_limit:
            raise ValueError("default page_size exceeds max_limit")
        return 10
    if type(value) is not int:
        raise TypeError("page_size must be an integer")
    if not 1 <= value <= max_limit:
        raise ValueError("page_size out of range")
    return value

