import sys
sys.path.insert(0, "/workspace")
from paging import page_size
assert page_size() == 10
assert page_size(1) == 1
assert page_size(100) == 100
assert page_size(250, max_limit=300) == 250
for bad in (0, -1, 101):
    try:
        page_size(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f"accepted out-of-range page size: {bad}")
for bad_limit in (0, 501):
    try:
        page_size(10, max_limit=bad_limit)
    except ValueError:
        pass
    else:
        raise AssertionError(f"accepted out-of-range max_limit: {bad_limit}")
for bad in (False, True, 2.5, "2"):
    try:
        page_size(bad)
    except TypeError:
        pass
    else:
        raise AssertionError(f"accepted invalid page size type: {bad!r}")
for bad_limit_type in (False, True, 100.0, "100", None):
    try:
        page_size(10, max_limit=bad_limit_type)
    except TypeError:
        pass
    else:
        raise AssertionError(f"accepted invalid max_limit type: {bad_limit_type!r}")
